package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamBioCellsBank1 {
  private const val T = "ජීවයේ රසායනික පදනම, සෛලය හා වර්ගීකරණය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "ජීව විද්‍යා විෂය නිර්දේශයට අදාළ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("ජීවී දේහවල බහුලවම අඩංගු වන අකාබනික සංයෝගය කුමක්ද?", "ජලය", "ඛනිජ ලවණ", "කාබෝහයිඩ්‍රේට", "ලිපිඩ", "ජීවී සෛලයක බරින් 70%–90% පමණ ජලය වේ."),
    q("කාබෝහයිඩ්‍රේට අණුවක හයිඩ්‍රජන් හා ඔක්සිජන් පරමාණු අතර අනුපාතය කුමක්ද?", "2:1", "1:1", "1:2", "3:1", "කාබෝහයිඩ්‍රේටවල පොදු සූත්‍රය Cₓ(H₂O)ᵧ බැවින් H:O අනුපාතය 2:1 වේ."),
    q("පහත සඳහන් කාබෝහයිඩ්‍රේට අතරින් මොනොසැකරයිඩයක් නොවන්නේ කුමක්ද?", "සුක්‍රෝස්", "ග්ලූකෝස්", "ෆ්‍රක්ටෝස්", "ගැලැක්ටෝස්", "සුක්‍රෝස් යනු ඩයිසැකරයිඩයකි."),
    q("පළතුරුවල ස්වභාවිකවම බහුලව අඩංගු වන පැණි රසැති මොනොසැකරයිඩය කුමක්ද?", "ෆ්‍රක්ටෝස්", "ලැක්ටෝස්", "මෝල්ටෝස්", "සෙලියුලෝස්", "ෆ්‍රක්ටෝස් 'පළතුරු සීනි' ලෙස හැඳින්වේ."),
    q("කිරිවල ස්වභාවිකව අඩංගු වන ඩයිසැකරයිඩය කුමක්ද?", "ලැක්ටෝස්", "මෝල්ටෝස්", "සුක්‍රෝස්", "ග්ලයිකෝජන්", "ග්ලූකෝස් හා ගැලැක්ටෝස් එක්ව ලැක්ටෝස් සෑදේ."),
    q("උක් ගසේ යුෂයේ බහුලව අඩංගු වන ඩයිසැකරයිඩය කුමක්ද?", "සුක්‍රෝස්", "ලැක්ටෝස්", "මෝල්ටෝස්", "ග්ලූකෝස්", "ග්ලූකෝස් හා ෆ්‍රක්ටෝස් එක්වීමෙන් සුක්‍රෝස් සෑදේ."),
    q("ප්‍රරෝහණය වන බීජවල බහුලව අඩංගු ඩයිසැකරයිඩය කුමක්ද?", "මෝල්ටෝස්", "සුක්‍රෝස්", "ලැක්ටෝස්", "ගැලැක්ටෝස්", "පිෂ්ඨය ජීර්ණය වීමෙන් මෝල්ටෝස් සෑදේ."),
    q("සත්ව දේහවල අක්මාවේ හා පේශිවල සංචිත කෙරෙන පොලිසැකරයිඩය කුමක්ද?", "ග්ලයිකෝජන්", "පිෂ්ඨය", "සෙලියුලෝස්", "කයිටින්", "සතුන් අතිරික්ත ග්ලූකෝස් ග්ලයිකෝජන් ලෙස ගබඩා කරයි."),
    q("ශාක සෛල බිත්තිය සෑදීමට දායක වන ව්‍යුහමය පොලිසැකරයිඩය කුමක්ද?", "සෙලියුලෝස්", "පිෂ්ඨය", "ග්ලයිකෝජන්", "සුක්‍රෝස්", "සෙලියුලෝස් ශාක සෛල බිත්තියට දෘඪ බව ලබා දෙයි."),
    q("බෙනඩික්ට් ද්‍රාවණය සමඟ රත් කළ විට ගඩොල් රතු අවක්ෂේපයක් ලබා නොදෙන සීනි වර්ගය කුමක්ද?", "සුක්‍රෝස්", "ග්ලූකෝස්", "ෆ්‍රක්ටෝස්", "මෝල්ටෝස්", "සුක්‍රෝස් අනොක්සිහාරක සීනි වර්ගයකි."),
    q("පිෂ්ඨය හඳුනාගැනීම සඳහා යොදා ගන්නා රසායනික ප්‍රතිකාරකය කුමක්ද?", "අයඩින් ද්‍රාවණය", "බෙනඩික්ට් ද්‍රාවණය", "බයියුරෙට් ප්‍රතිකාරකය", "සුඩාන් III ද්‍රාවණය", "පිෂ්ඨය හමුවේ අයඩින් ද්‍රාවණය තද නිල්-කළු පැහැයට හැරේ."),
    q("ප්‍රෝටීන තැනී ඇති මූලික තැනුම් ඒකක මොනවාද?", "ඇමයිනෝ අම්ල", "මේද අම්ල", "මොනොසැකරයිඩ", "නියුක්ලියෝටයිඩ", "ඇමයිනෝ අම්ල පෙප්ටයිඩ බන්ධනවලින් බැඳී ප්‍රෝටීන සාදයි."),
    q("සියලුම ප්‍රෝටීනවල අනිවාර්යයෙන්ම අඩංගු වන මූලද්‍රව්‍ය හතර මොනවාද?", "C, H, O, N", "C, H, O, P", "C, H, N, Cl", "C, O, S, Fe", "සියලු ප්‍රෝටීනවල කාබන්, හයිඩ්‍රජන්, ඔක්සිජන් සහ නයිට්‍රජන් අඩංගු වේ."),
    q("ආහාර සාම්පලයකට NaOH සහ තනුක CuSO₄ බිංදු කිහිපයක් එක් කළ විට දම් පැහැයක් ඇති වූයේ නම් එහි අඩංගු වන්නේ කුමක්ද?", "ප්‍රෝටීන", "පිෂ්ඨය", "ලිපිඩ", "ග්ලූකෝස්", "බයියුරෙට් පරීක්ෂාවෙන් ප්‍රෝටීන දම් පැහැයක් ලබා දෙයි."),
    q("ජෛව රසායනික ප්‍රතික්‍රියා උත්ප්‍රේරණය කරන විශේෂිත ප්‍රෝටීන හඳුන්වන්නේ කුමන නමින්ද?", "එන්සයිම", "හෝමෝන", "ප්‍රතිදේහ", "විටමින්", "එන්සයිම ජෛව උත්ප්‍රේරක ලෙස ක්‍රියා කරයි."),
    q("ලිපිඩ අණුවක් සෑදීමට ග්ලිසරෝල් සමඟ සම්බන්ධ වන අනෙක් සංඝටකය කුමක්ද?", "මේද අම්ල", "ඇමයිනෝ අම්ල", "ග්ලූකෝස්", "නියුක්ලියෝටයිඩ", "මේද අම්ල තුනක් සහ ග්ලිසරෝල් අණුවක් එක්ව ට්‍රයිග්ලිසරයිඩ සෑදේ."),
    q("ලිපිඩ හඳුනාගැනීමේ සුඩාන් III පරීක්ෂාවේදී ලැබෙන ධනාත්මක නිරීක්ෂණය කුමක්ද?", "රතු පැහැති ගෝලිකා තට්ටුවක්", "දම් පැහැති ද්‍රාවණයක්", "ගඩොල් රතු අවක්ෂේපයක්", "නිල්-කළු පැහැයක්", "සුඩාන් III රංජකය ලිපිඩ තුළ දියවී රතු තට්ටුවක් සාදයි."),
    q("සෛල පටලයේ ප්‍රධාන ව්‍යුහමය සංඝටකය වන ලිපිඩ විශේෂය කුමක්ද?", "පොස්ෆොලිපිඩ", "ඉටි", "කොලෙස්ටරෝල්", "ට්‍රයිග්ලිසරයිඩ", "සෛල පටලය පොස්ෆොලිපිඩ ද්වි-ස්තරයකින් සෑදී ඇත."),
    q("සමාන ස්කන්ධයක් සලකන විට වැඩිම ශක්ති ප්‍රමාණයක් මුදාහරින ආහාර සංඝටකය කුමක්ද?", "ලිපිඩ", "කාබෝහයිඩ්‍රේට", "ප්‍රෝටීන", "විටමින්", "ලිපිඩ ග්‍රෑම් 1 කින් කාබෝහයිඩ්‍රේට මෙන් දෙගුණයකට වඩා ශක්තිය ලැබේ."),
    q("DNA අණුවක තැනුම් ඒකකය හඳුන්වන්නේ කුමන නමින්ද?", "නියුක්ලියෝටයිඩය", "ඇමයිනෝ අම්ලය", "මොනොසැකරයිඩය", "පෙප්ටයිඩය", "න්‍යෂ්ටික අම්ල නියුක්ලියෝටයිඩ බහුඅවයවික වේ."),
    q("DNA අණුවක නොමැති නමුත් RNA අණුවක පමණක් අඩංගු වන නයිට්‍රජනීය භෂ්මය කුමක්ද?", "යුරැසිල්", "ඇඩිනීන්", "ගුවැනීන්", "සයිටොසීන්", "DNA හි තයිමින් අඩංගු වන අතර RNA හි ඒ වෙනුවට යුරැසිල් පවතී."),
    q("DNA අණුවේ ද්විත්ව හෙලික්සාකාර ආකෘතිය ඉදිරිපත් කළ විද්‍යාඥයන් දෙදෙනා කවුද?", "වොට්සන් සහ ක්‍රික්", "මෙන්ඩල් සහ ඩාවින්", "හුක් සහ ලීවන්හුක්", "ෂ්ලයිඩන් සහ ෂ්වාන්", "1953 දී ජේම්ස් වොට්සන් සහ ෆ්‍රැන්සිස් ක්‍රික් DNA ආකෘතිය හඳුන්වා දුන්හ."),
    q("රාත්‍රී අන්ධතාව (රාත්‍රියේදී ඇස් නොපෙනීම) ඇතිවන්නේ කුමන විටමිනයේ ඌනතාව නිසාද?", "විටමින් A", "විටමින් B", "විටමින් C", "විටමින් D", "රෙටිනෝල් හෙවත් විටමින් A ඌනතාව බිටෝ ලප සහ රාත්‍රී අන්ධතාව ඇති කරයි."),
    q("විදුරුමස්වලින් ලේ ගැලීමේ රෝගය (ස්කර්වි) ඇතිවන්නේ කුමන විටමිනයේ ඌනතාව නිසාද?", "විටමින් C", "විටමින් A", "විටමින් D", "විටමින් K", "ඇස්කෝබික් අම්ලය (විටමින් C) ඌනතාව නිසා ස්කර්වි රෝගය හටගනී."),
    q("කුඩා දරුවන්ගේ අස්ථි දුර්වල වී නැමෙන රිකට්ස් රෝගය වළක්වා ගැනීමට අවශ්‍ය විටමිනය කුමක්ද?", "විටමින් D", "විටමින් E", "විටමින් K", "විටමින් B₁₂", "විටමින් D කැල්සියම් සහ පොස්පරස් අවශෝෂණයට උපකාරී වේ."),
    q("රුධිරය කැටි ගැසීමේ ක්‍රියාවලිය සඳහා අත්‍යවශ්‍ය වන විටමිනය කුමක්ද?", "විටමින් K", "විටමින් A", "විටමින් C", "විටමින් E", "රුධිර කැටි ගැසීමේ සාධක සංස්ලේෂණයට විටමින් K අවශ්‍ය වේ."),
    q("ජලයේ ද්‍රාව්‍ය වන විටමින් කාණ්ඩය කුමක්ද?", "විටමින් B හා C", "විටමින් A හා D", "විටමින් D හා E", "විටමින් A හා K", "විටමින් B සංකීර්ණය සහ C ජලයේ ද්‍රාව්‍ය වන අතර A, D, E, K මේදයේ ද්‍රාව්‍ය වේ."),
    q("තයිරොක්සින් හෝමෝනය නිපදවීමට අවශ්‍ය වන ඛනිජ මූලද්‍රව්‍යය කුමක්ද?", "අයඩින්", "යකඩ", "කැල්සියම්", "සෝඩියම්", "අයඩින් ඌනතාව නිසා ගලගණ්ඩය ඇතිවේ."),
    q("හිමොග්ලොබින් අණුවේ මධ්‍යයේ අඩංගු වන ඛනිජ මූලද්‍රව්‍යය කුමක්ද?", "යකඩ", "මැග්නීසියම්", "කැල්සියම්", "පොටෑසියම්", "යකඩ ඌනතාව නිසා නීරක්තිය (රක්තහීනතාව) ඇතිවේ."),
    q("ශාක පත්‍රවල හරිතප්‍රද (ක්ලෝරොෆිල්) සංස්ලේෂණය සඳහා අත්‍යවශ්‍ය ඛනිජ මූලද්‍රව්‍යය කුමක්ද?", "මැග්නීසියම්", "කැල්සියම්", "සෝඩියම්", "ක්ලෝරීන්", "මැග්නීසියම් ඌනතාව නිසා පත්‍ර කහ පැහැ ගැන්වේ (ක්ලෝරෝසිස්)."),
    q("ශාක පත්‍ර අග්‍ර හා දාර මැරී යාමේ රෝග ලක්ෂණය බහුලව පෙන්නුම් කරන්නේ කුමන ඛනිජ ඌනතාව නිසාද?", "පොටෑසියම්", "නයිට්‍රජන්", "මැග්නීසියම්", "යකඩ", "පොටෑසියම් ඌනතාව නිසා පත්‍ර අග්‍ර පිළිස්සී මැරී යයි."),
    q("ජලයේ ඉහළ විශිෂ්ට තාප ධාරිතාව ජීවීන්ට වැදගත් වන්නේ කෙසේද?", "දේහ උෂ්ණත්වය නියතව තබා ගැනීමට", "රසායනික ප්‍රතික්‍රියා නැවැත්වීමට", "සෛල බිත්ති දෘඪ කිරීමට", "ආලෝකය පරාවර්තනය කිරීමට", "ජලය තාපය විශාල ප්‍රමාණයක් අවශෝෂණය කර ගැනීම නිසා උෂ්ණත්ව විචලනය අවම වේ."),
    q("සජීවී සෛල ප්‍රථම වරට අන්වීක්ෂයෙන් නිරීක්ෂණය කළ විද්‍යාඥයා කවුද?", "ඇන්ටන් වෑන් ලීවන්හුක්", "රොබට් හුක්", "රොබට් බ්‍රවුන්", "තියඩෝර් ෂ්වාන්", "ලීවන්හුක් 1674 දී පොකුණු ජලයේ සජීවී ඒකසෛලික ජීවීන් නිරීක්ෂණය කළේය."),
    q("සෛලයේ 'ශක්ති බලාගාරය' ලෙස හඳුන්වන ඉන්ද්‍රයිකාව කුමක්ද?", "මයිටොකොන්ඩ්‍රියාව", "ගොල්ගි දේහය", "රයිබොසෝමය", "ලයසොසෝමය", "සෛලීය ශ්වසනය මඟින් ATP නිපදවීම මයිටොකොන්ඩ්‍රියාවේ සිදුවේ."),
    q("පටලයකින් වට නොවූ සෛලීය ඉන්ද්‍රයිකාවක් වන්නේ කුමක්ද?", "රයිබොසෝමය", "මයිටොකොන්ඩ්‍රියාව", "හරිතලවය", "ලයසොසෝමය", "රයිබොසෝම හා කේන්ද්‍රදේහ පටල රහිත ඉන්ද්‍රයිකා වේ."),
    q("ශාක සෛලයකට පමණක් ආවේණික වූ ව්‍යුහය කුමක්ද?", "සෙලියුලෝස් සෛල බිත්තිය", "ප්ලාස්ම පටලය", "මයිටොකොන්ඩ්‍රියාව", "ගොල්ගි දේහය", "සත්ව සෛලවල සෛල බිත්ති හා හරිතලව නොමැත."),
    q("සත්ව සෛලවල සෛල විභාජනයේදී තර්කු තන්තු සෑදීමට උපකාරී වන ඉන්ද්‍රයිකාව කුමක්ද?", "කේන්ද්‍රදේහය", "රයිබොසෝමය", "හරිතලවය", "රික්තකය", "සත්ව සෛලවල කේන්ද්‍රදේහ තුළ කේන්ද්‍රිකා යුගලක් පවතී."),
    q("ශාක සෛලයේ මධ්‍ය රික්තකය වටකර ඇති තනි පටලය හඳුන්වන්නේ කුමන නමින්ද?", "ටෝනොප්ලාස්ටය", "ප්ලාස්ම පටලය", "ක්‍රිස්ටා", "සෛල බිත්තිය", "රික්තක පටලය ටෝනොප්ලාස්ටය ලෙස හැඳින්වේ."),
    q("මතුපිට රයිබොසෝම සවි වී ඇති අන්තඃප්ලාස්මීය ජාලිකා විශේෂයේ ප්‍රධාන කාර්යය කුමක්ද?", "ප්‍රෝටීන පරිවහනය කිරීම", "ලිපිඩ සංස්ලේෂණය කිරීම", "DNA ප්‍රතිවලිත කිරීම", "ATP නිපදවීම", "රළු අන්තඃප්ලාස්මීය ජාලිකාව ප්‍රෝටීන සංස්ලේෂණය හා පරිවහනය කරයි."),
    q("සෛලය තුළ ඇති විෂ ද්‍රව්‍ය හරණය කිරීම හා ලිපිඩ සංස්ලේෂණය සිදු කරන්නේ කුමන ඉන්ද්‍රයිකාවද?", "සුමට අන්තඃප්ලාස්මීය ජාලිකාව", "රළු අන්තඃප්ලාස්මීය ජාලිකාව", "හරිතලවය", "කේන්ද්‍රදේහය", "සුමට අන්තඃප්ලාස්මීය ජාලිකාවේ රයිබොසෝම නොමැත."),
    q("සෛලයේ ස්‍රාවී ද්‍රව්‍ය පැකට් කර පිටතට මුදාහැරීම සිදු කරන ඉන්ද්‍රයිකාව කුමක්ද?", "ගොල්ගි සංකීර්ණය", "මයිටොකොන්ඩ්‍රියාව", "න්‍යෂ්ටිකාව", "කේන්ද්‍රදේහය", "ගොල්ගි දේහ මඟින් ස්‍රාවී බිබිලිකා නිපදවයි."),
    q("ජීවී සෛලයක සියලු ක්‍රියාකාරකම් පාලනය කරන මධ්‍යස්ථානය කුමක්ද?", "න්‍යෂ්ටිය", "රික්තකය", "රයිබොසෝමය", "සෛල ප්ලාස්මය", "න්‍යෂ්ටිය තුළ ප්‍රවේණික ද්‍රව්‍ය අඩංගු වේ."),
    q("ප්ලාස්ම පටලයේ ස්වභාවය නිවැරදිව විස්තර කරන යෙදුම කුමක්ද?", "වරණීය පාරගම්‍ය පටලය", "සම්පූර්ණ පාරගම්‍ය පටලය", "අපාරගම්‍ය පටලය", "දෘඪ පටලය", "ප්ලාස්ම පටලය තෝරාගත් අණුවලට පමණක් ගමන් කිරීමට ඉඩ දෙයි."),
    q("ප්‍රාග්න්‍යෂ්ටික සෛලයකට උදාහරණයක් වන්නේ පහත සඳහන් කුමන ජීවියාද?", "බැක්ටීරියාවක්", "ඇමීබාවෙක්", "යීස්ට් සෛලයක්", "පැරමීසියම්", "බැක්ටීරියා සෛලවල න්‍යෂ්ටි පටලයක් නොමැත."),
    q("ද්විගුණ (2n) සෛලයකින් ජානමය වශයෙන් සමාන ද්විගුණ දුහිතෘ සෛල දෙකක් සාදන සෛල විභාජන ක්‍රමය කුමක්ද?", "අනූනන විභාජනය", "ඌනන විභාජනය", "ද්විඛණ්ඩනය", "අංකුරණය", "අනූනනය මඟින් වර්ධනය හා ගෙවී ගිය පටක අලුත්වැඩියාව සිදුවේ."),
    q("ජන්මාණු (ශුක්‍රාණු හා ඩිම්බ) නිපදවීමේදී සිදුවන සෛල විභාජන ක්‍රමය කුමක්ද?", "ඌනන විභාජනය", "අනූනන විභාජනය", "සෘජු විභාජනය", "බහු ඛණ්ඩනය", "ඌනන විභාජනයෙන් වර්ණදේහ සංඛ්‍යාව අඩකින් අඩු වී ඒකගුණ (n) සෛල හතරක් සෑදේ."),
    q("මිනිසාගේ සාමාන්‍ය දේහ සෛලයක ඇති මුළු වර්ණදේහ සංඛ්‍යාව කීයද?", "46", "23", "44", "48", "මිනිසාගේ 2n සංඛ්‍යාව 46 කි (යුගල 23 කි)."),
    q("ඌනන විභාජනයේදී ප්‍රවේණික විවිධත්වය ඇතිවීමට ප්‍රධාන වශයෙන් බලපාන සිදුවීම කුමක්ද?", "අවතැන් වීම (Crossing over)", "DNA අර්ධ වීම", "සෛල ප්ලාස්ම බෙදීම", "න්‍යෂ්ටි පටලය සෑදීම", "සමජාත වර්ණදේහ අතර ජාන කොටස් හුවමාරු වීමෙන් නව ප්‍රභේදන ඇතිවේ."),
    q("මිනිසාගේ ශුක්‍රාණුවක අඩංගු වර්ණදේහ සංඛ්‍යාව කීයද?", "23", "46", "22", "44", "ජන්මාණු ඒකගුණ (n = 23) වේ."),
    q("අනූනන විභාජනයේ කුමන අවධියේදී වර්ණදේහ සෛලයේ සමක තලය මත පෙළ ගැසේද?", "යෝග කලාව (Metaphase)", "ප්‍රාක් කලාව (Prophase)", "වියෝග කලාව (Anaphase)", "අන්ත කලාව (Telophase)", "සමක තලයේ පෙළ ගැසීම යෝග කලාවේ ප්‍රධාන ලක්ෂණයකි."),
    q("ද්විපද නාමකරණ ක්‍රමය ලොවට හඳුන්වා දුන් විද්‍යාඥයා කවුද?", "කැරොලස් ලිනේයස්", "චාල්ස් ඩාවින්", "ඇරිස්ටෝටල්", "රොබට් විටේකර්", "ස්වීඩන් ජාතික කැරොලස් ලිනේයස් විද්‍යාත්මක නාමකරණය හඳුන්වා දුන්නේය."),
    q("ද්විපද නාමකරණය අනුව 'Homo sapiens' යන විද්‍යාත්මක නාමයේ 'Homo' යන්නෙන් දැක්වෙන්නේ කුමක්ද?", "ගණ නාමය", "සුළු නාමය", "කුල නාමය", "වංශ නාමය", "පළමු පදය ගණ නාමය වන අතර එය කැපිටල් අකුරකින් ආරම්භ වේ."),
    q("පංච රාජධානි වර්ගීකරණය ඉදිරිපත් කළ විද්‍යාඥයා කවුද?", "රොබට් විටේකර්", "කාල් වූස්", "ලිනේයස්", "ලැමාක්", "මොනේරා, ප්‍රොටිස්ටා, ෆන්ගයි, ප්ලාන්ටේ, ඇනිමාලියා යනු රාජධානි පහයි."),
    q("පහත සඳහන් රාජධානි අතරින් ප්‍රාග්න්‍යෂ්ටික ජීවීන් අයත් වන්නේ කුමන රාජධානියටද?", "මොනේරා", "ප්‍රොටිස්ටා", "ෆන්ගයි", "ප්ලාන්ටේ", "සියලු බැක්ටීරියා සහ සයනොබැක්ටීරියා මොනේරා රාජධානියට අයත් වේ."),
    q("ඇමීබා, පැරමීසියම් සහ යුග්ලීනා යන ඒකසෛලික සූන්‍යෂ්ටික ජීවීන් අයත් රාජධානිය කුමක්ද?", "ප්‍රොටිස්ටා", "මොනේරා", "ෆන්ගයි", "ඇනිමාලියා", "සරල සූන්‍යෂ්ටික ජීවීන් ප්‍රොටිස්ටා රාජධානියට අයත් වේ."),
    q("දිලීර (ෆන්ගයි) සෛල බිත්තිය සෑදී ඇති රසායනික ද්‍රව්‍යය කුමක්ද?", "කයිටින්", "සෙලියුලෝස්", "පෙප්ටිඩොග්ලයිකෑන්", "ලිග්නින්", "දිලීර සෛල බිත්තියේ කයිටින් අඩංගු වන අතර හරිතප්‍රද නොමැත."),
    q("හතු, පාන් පුස් සහ යීස්ට් යන ජීවීන්ගේ පොදු පෝෂණ ක්‍රමය කුමක්ද?", "මෘතෝපජීවී පෝෂණය", "ස්වයංපෝෂී පෝෂණය", "ප්‍රභාස්වයංපෝෂී", "රසායනික ස්වයංපෝෂී", "දිලීර අජීවී කාබනික ද්‍රව්‍ය මත බාහිර ජීර්ණ එන්සයිම ශ්‍රාවය කර පෝෂණය ලබයි."),
    q("පුෂ්ප හට නොගන්නා නමුත් සනාල පටක සහ සැබෑ මුල්, කඳ, පත්‍ර ඇති ශාක කාණ්ඩය කුමක්ද?", "ටෙරයිඩොෆයිටා (මීවන)", "බ්‍රයොෆයිටා (හරිත දිය සෙවෙල්)", "ජිම්නොස්පර්ම්", "ඇන්ජියොස්පර්ම්", "මීවන ශාකවල පුෂ්ප නැති අතර බීජාණු මඟින් ප්‍රජනනය සිදු කරයි."),
    q("විවෘත බීජ හටගන්නා ශාකවලට (ජිම්නොස්පර්ම්) උදාහරණයක් වන්නේ කුමක්ද?", "මඩු (Cycas)", "පොල්", "අඹ", "නෙෆ්‍රොලෙපිස්", "මඩු සහ පයිනස් වැනි ශාකවල බීජ ඵලයකින් ආවරණය වී නොමැත."),
    q("ඒකබීජ පත්‍රී ශාකයක සාමාන්‍යයෙන් දැකිය හැකි ලක්ෂණය කුමක්ද?", "සමාන්තර නාරටි වින්‍යාසය", "මුදුන් මූල පද්ධතිය", "පංචාංගික පුෂ්ප", "ද්විතීයික වර්ධනය", "තෘණ, පොල්, වී වැනි ඒකබීජ පත්‍රී ශාකවල තන්තු මූල හා සමාන්තර නාරටි ඇත."),
    q("ද්විබීජ පත්‍රී ශාකයක ලක්ෂණයක් වන්නේ පහත සඳහන් කුමක්ද?", "ජාලාභ නාරටි වින්‍යාසය", "තන්තු මූල පද්ධතිය", "ත්‍රිඅංගික පුෂ්ප", "එක් බීජ පත්‍රයක් තිබීම", "ද්විබීජ පත්‍රී ශාකවල මුදුන් මූල පද්ධතියක් සහ ජාලාභ නාරටි පවතී."),
    q("සත්ව රාජධානියේ ශරීරය අරීය සමමිතියක් පෙන්වන සහ දංශක කෝෂ්ඨ ඇති වංශය කුමක්ද?", "නිඩාරියා (Cnidaria)", "ප්ලැටිහෙල්මින්තස්", "ඇනෙලිඩා", "ආත්‍රොපෝඩා", "හයිඩ්‍රා, ජෙලිෆිෂ් සහ මුහුදු මල් නිඩාරියා වංශයට අයත් වේ."),
    q("සන්ධිමත් උපාංග සහ කයිටින්මය බාහිර සැකිල්ලක් ඇති සත්ව වංශය කුමක්ද?", "ආත්‍රොපෝඩා", "මොලුස්කා", "එකයිනොඩර්මේටා", "ඇනෙලිඩා", "කෘමීන්, මකුළුවන් හා කකුළුවන් ආත්‍රොපෝඩා වංශයට අයත් වේ."),
    q("කණ්ඩනය වූ දේහයක් ඇති ගැඩවිලා සහ කූඩැල්ලා අයත් වන වංශය කුමක්ද?", "ඇනෙලිඩා", "නෙමටෝඩා", "ප්ලැටිහෙල්මින්තස්", "මොලුස්කා", "ඇනෙලිඩා සතුන්ගේ දේහය බාහිර හා අභ්‍යන්තර කණ්ඩවලට බෙදී ඇත."),
    q("මෘදු දේහයක් සහ කැල්සියම් කාබනේට් කවචයක් දරන ගොළුබෙල්ලා අයත් වංශය කුමක්ද?", "මොලුස්කා", "එකයිනොඩර්මේටා", "නිඩාරියා", "ආත්‍රොපෝඩා", "ගොළුබෙල්ලා, දැල්ලා සහ බෙල්ලා මොලුස්කා වංශයට අයත් වේ."),
    q("පංච අරීය සමමිතිය හා නාල පාද සහිත සමුද්‍රවාසී සත්ව වංශය කුමක්ද?", "එකයිනොඩර්මේටා", "මොලුස්කා", "නිඩාරියා", "ඇනෙලිඩා", "තාරකා මත්ස්‍යයා සහ මුහුදු කැකිරි මෙම වංශයට අයත් වේ."),
    q("අභ්‍යන්තර කාටිලේජමය සැකිල්ලක් ඇති මත්ස්‍යයෙකු වන්නේ කවුද?", "මෝරා", "කෙලවල්ලා", "තිලාපියා", "සාලයා", "මෝරා සහ මඩුවා කාටිලේජමය මසුන් වේ."),
    q("ශ්වසනය සඳහා පෙනහැලි මෙන්ම තෙත් සම ද භාවිත කරන පෘෂ්ඨවංශී කාණ්ඩය කුමක්ද?", "ඇම්ෆිබියා (උභයජීවීන්)", "රෙප්ටීලියා (උරගයින්)", "පිසේස් (මසුන්)", "ආවේස් (පක්ෂීන්)", "ගෙම්බා සහ සැලමැන්ඩරය ජලයේදී හා ගොඩබිමදී ජීවත් වේ."),
    q("කුටීර හතරකින් යුත් හෘදයක් ඇති අචලතාපී (උණුසුම් රුධිරය ඇති) කාණ්ඩ දෙක මොනවාද?", "පක්ෂීන් සහ ක්ෂීරපායීන්", "මසුන් සහ උභයජීවීන්", "උභයජීවීන් සහ උරගයින්", "මසුන් සහ උරගයින්", "පක්ෂීන් හා ක්ෂීරපායීන් පරිසර උෂ්ණත්වය අනුව දේහ උෂ්ණත්වය වෙනස් නොකරයි."),
    q("බිත්තර දමන ක්ෂීරපායී සත්වයෙකුට උදාහරණයක් වන්නේ කවුද?", "ප්ලැටිපස්", "කැන්ගරුවා", "වවුලා", "තල්මසා", "ප්ලැටිපස් සහ එකිඩ්නා බිත්තර දැමුවද පැටවුන්ට කිරි පොවයි."),
    q("වෛරස සජීවී ලක්ෂණයක් පෙන්වන්නේ කුමන අවස්ථාවේදී පමණක්ද?", "ධාරක සෛලයක් තුළට ඇතුළු වූ විට", "වියළි පසෙහි ඇති විට", "අධික සීතලේ ඇති විට", "ආස්‍රැත ජලයේ ඇති විට", "වෛරස ධාරක සෛලයෙන් පිටතදී අජීවී ස්ඵටික ලෙස පවතී."),
    q("ජීවී දේහවල ප්‍රධාන වශයෙන් ශක්තිය සපයන මූලික කාබෝහයිඩ්‍රේටය කුමක්ද?", "ග්ලූකෝස්", "සෙලියුලෝස්", "කයිටින්", "ලැක්ටෝස්", "සෛලීය ශ්වසනයේ ප්‍රධාන උපස්තරය ග්ලූකෝස් වේ."),
    q("පත්‍රිකා විශාල සංඛ්‍යාවක් පිහිටි සංයුක්ත පත්‍ර ඇති නමුත් විවෘත බීජ දරන ශාකය කුමක්ද?", "මඩු", "කොස්", "අඹ", "වී", "මඩු (Cycas) ශාකය විවෘත බීජකයෙකි."),
    q("පෘෂ්ඨවංශීන් අතරින් ප්‍රථම වරට පූර්ණ සිව් කුටීර හෘදයක් දැකිය හැකි උරගයා කවුද?", "කිඹුලා", "කැස්බෑවා", "නයා", "කටුස්සා", "සාමාන්‍ය උරගයින්ගේ කුටීර තුනක් පවතින නමුත් කිඹුලාගේ කුටීර හතරකි."),
    q("ජලයේ ජීවත් වන ක්ෂීරපායී සත්වයෙකු වන්නේ කවුද?", "ඩොල්ෆින්", "තෝරා", "කිඹුලා", "කැස්බෑවා", "ඩොල්ෆින් සහ තල්මසා පෙනහැලිවලින් හුස්ම ගන්නා ක්ෂීරපායීන් වේ."),
    q("පියෑඹීමේ හැකියාව ඇති එකම ක්ෂීරපායී සත්වයා කවුද?", "වවුලා", "මොනරා", "උකුස්සා", "කපුටා", "වවුලාගේ පූර්ව ගාත්‍රා පියාපත් ලෙස විකරණය වී ඇත."),
    q("පැතැලි පණුවන් අයත් වන ප්ලැටිහෙල්මින්තස් වංශයේ සත්වයෙකු වන්නේ කවුද?", "ප්ලැනේරියා", "වට පණුවා", "ගැඩවිලා", "කූඩැල්ලා", "ප්ලැනේරියා, පටි පණුවා හා අක්මා පත්‍රිකාව පැතැලි පණුවන් වේ."),
    q("සංයුක්ත ආලෝක අන්වීක්ෂයක උපනෙතේ විශාලනය ×10 ක් සහ අවනෙතේ විශාලනය ×40 ක් නම් මුළු විශාලනය කීයද?", "×400", "×50", "×4", "×100", "මුළු විශාලනය = උපනෙත් විශාලනය × අවනෙත් විශාලනය = 10 × 40 = 400."),
    q("සෛලයේ ජානමය තොරතුරු අඩංගු වර්ණදේහ තැනී ඇත්තේ කුමන ද්‍රව්‍ය දෙකෙන්ද?", "DNA සහ ප්‍රෝටීන", "RNA සහ ලිපිඩ", "ග්ලූකෝස් සහ ප්‍රෝටීන", "සෙලියුලෝස් සහ DNA", "වර්ණදේහ DNA හා හිස්ටෝන් ප්‍රෝටීන වලින් සමන්විත වේ."),
    q("ශාක පත්‍ර හා කඳන් මතුපිට ජල හානිය වැළැක්වීමට පිහිටි ඉටිමය ස්තරය කුමක්ද?", "උච්චර්මය (Cuticle)", "ප්ලාස්ම පටලය", "එන්ඩොඩර්මිසය", "කැම්බියම", "උච්චර්මය ජල වාෂ්ප පිටවීම අවම කරයි."),
    q("පාන් සෑදීමේදී පිටි පිපීමට හේතු වන ඒකසෛලික දිලීරය කුමක්ද?", "යීස්ට්", "ඇස්පර්ජිලස්", "පෙනිසිලියම්", "මියුකර්", "යීස්ට් නිර්වායු ශ්වසනයෙන් CO₂ වායුව නිපදවයි."),
    q("සෛල ප්ලාස්මයේ සිට ද්‍රව්‍ය න්‍යෂ්ටිය තුළට හෝ ඉන් පිටතට ගමන් කරන්නේ කුමක් හරහාද?", "න්‍යෂ්ටික සිදුරු", "රයිබොසෝම", "සෛල බිත්ති සිදුරු", "ප්ලාස්ම බන්ධ", "න්‍යෂ්ටි පටලයේ න්‍යෂ්ටික සිදුරු පිහිටා ඇත."),
    q("සෛලයක ස්වයං-ජීර්ණය (Autolysis) සිදු කිරීමට හැකි එන්සයිම අඩංගු ඉන්ද්‍රයිකාව කුමක්ද?", "ලයසොසෝමය", "රයිබොසෝමය", "හරිතලවය", "කේන්ද්‍රිකාව", "ලයසොසෝමවල ජලවිච්ඡේදක එන්සයිම අඩංගු වේ."),
    q("ශ්වසන පෘෂ්ඨ තෙත්ව තබා ගැනීමටත්, පටකවලට ආරක්ෂාව සැපයීමටත් දායක වන දේහ අභ්‍යන්තර තරලය කුමක්ද?", "ජලය", "තෙල්", "පිෂ්ඨය", "සෙලියුලෝස්", "ජලය ජීවී දේහවල ප්‍රධාන මාධ්‍යය වේ."),
    q("ස්නායු පටකයේ මූලික ව්‍යුහමය හා කෘත්‍යමය ඒකකය කුමක්ද?", "නියුරෝනය", "නෙෆ්‍රෝනය", "සාර්කොමියරය", "ගර්තය", "නියුරෝන මඟින් විද්‍යුත් ආවේග සම්ප්‍රේෂණය කෙරේ."),
    q("ශාකවල ආහාර හා ජලය පරිවහනය නොකරන, ප්‍රභාසංස්ලේෂණය හා ආහාර සංචිත කරන සරල පටකය කුමක්ද?", "මෘදුස්තරය", "සෛලමය", "ෆ්ලෝයමය", "දෘඪස්තරය", "මෘදුස්තර සෛල තුනී සෛල බිත්ති සහිත සජීවී සෛල වේ."),
    q("ශාකවලට යාන්ත්‍රික ශක්තිය සපයන ලිග්නින් තැන්පත් වූ අජීවී සෛල සහිත සරල ස්ථිර පටකය කුමක්ද?", "දෘඪස්තරය", "මෘදුස්තරය", "ස්ථූලකෝණාස්තරය", "විභාජක පටකය", "පොල් ලෙල්ලේ හා කජු ලෙල්ලේ දෘඪස්තර සෛල බහුල වේ."),
    q("ශාක මුල් හා කඳන්වල අග්‍රස්ථයේ පිහිටා ශාකයේ දිගින් වැඩිවීමට දායක වන පටකය කුමක්ද?", "අග්‍රස්ථ විභාජක පටකය", "පාර්ශ්වික විභාජක පටකය", "ස්ථිර පටකය", "දෘඪස්තර පටකය", "විභාජක පටක සෛල සක්‍රියව අනූනන විභාජනයට ලක්වේ."),
    q("ශාක කඳක පරිධිය (මහත) වැඩි කිරීමට හේතු වන පාර්ශ්වික විභාජක පටකය කුමක්ද?", "කැම්බියම", "මෘදුස්තරය", "සෛලමය", "අපිචර්මය", "සනාල කැම්බියම මඟින් ද්විතීයික වර්ධනය සිදුවේ."),
    q("සත්ව දේහයක අස්ථි දෙකක් එකිනෙක සම්බන්ධ කරන තන්තුමය සම්බන්ධක පටකය කුමක්ද?", "බන්ධනී (Ligaments)", "කණ්ඩරා (Tendons)", "කාටිලේජ", "මේද පටකය", "බන්ධනී අස්ථි-අස්ථි සම්බන්ධ කරන අතර කණ්ඩරා පේශි-අස්ථි සම්බන්ධ කරයි."),
    q("පේශියක් අස්ථියකට සවි කරන ශක්තිමත් සම්බන්ධක පටකය කුමක්ද?", "කණ්ඩරාව (Tendon)", "බන්ධනිය (Ligament)", "කාටිලේජය", "අපිච්ඡදය", "කණ්ඩරා ඇදෙන සුළු බව අඩු කොලැජන් තන්තුවලින් සෑදී ඇත."),
    q("මිනිස් හෘද බිත්තිය සෑදී ඇති විශේෂිත පේශි වර්ගය කුමක්ද?", "හෘත් පේශි පටකය", "සිනිඳු පේශි පටකය", "කංකාල පේශි පටකය", "සම්බන්ධක පටකය", "හෘත් පේශි අනිච්ඡානුග වන අතර විඩාවට පත් නොවේ."),
    q("ආහාර මාර්ගයේ බිත්තිවල සහ රුධිර නාලවල පිහිටි අනිච්ඡානුග පේශි වර්ගය කුමක්ද?", "සිනිඳු පේශි", "කංකාල පේශි", "හෘත් පේශි", "විලේඛ පේශි", "සිනිඳු පේශිවල තීර්යක් රේඛා නොමැති අතර තර්කු හැඩැති වේ."),
    q("රුධිරය අයත් වන්නේ සත්ව පටක වර්ග අතරින් කුමන ප්‍රධාන කාණ්ඩයටද?", "සම්බන්ධක පටකය", "අපිච්ඡද පටකය", "පේශි පටකය", "ස්නායු පටකය", "රුධිරය දියරමය පූරකයක් සහිත විශේෂිත සම්බන්ධක පටකයකි."),
    q("ජීවී වර්ගීකරණයේ මූලිකම හා කුඩාම ඒකකය කුමක්ද?", "විශේෂය (Species)", "ගණය (Genus)", "කුලය (Family)", "ගෝත්‍රය (Order)", "අන්තර් අභිජනනයෙන් සරු ජනිතයන් බිහි කළ හැකි ජීවී කාණ්ඩය විශේෂයයි."),
    q("වර්ගීකරණ ධුරාවලියේ 'ගණයට' ඉහළින් ඇති ඊළඟ මට්ටම කුමක්ද?", "කුලය (Family)", "විශේෂය (Species)", "වංශය (Phylum)", "රාජධානිය (Kingdom)", "පිළිවෙළ: විශේෂය → ගණය → කුලය → ගෝත්‍රය → වර්ගය → වංශය → රාජධානිය."),
    q("ජීවී සෛලවල ප්ලාස්ම පටලය හරහා අණු සාන්ද්‍රණ අනුක්‍රමණය ඔස්සේ ශක්තිය වැය නොකර ගමන් කිරීමේ ක්‍රියාවලිය කුමක්ද?", "විසරණය", "සක්‍රිය පරිවහනය", "අන්තඃභක්ෂණය", "බහිෂ්භක්ෂණය", "විසරණය හා ආස්‍රැතිය අක්‍රිය පරිවහන ක්‍රම වේ."),
    q("ශක්තිය (ATP) වැය කරමින් අඩු සාන්ද්‍රණයේ සිට වැඩි සාන්ද්‍රණයක් දෙසට අයන ගමන් කිරීම හඳුන්වන්නේ කෙසේද?", "සක්‍රිය පරිවහනය", "විසරණය", "ආස්‍රැතිය", "ප්ලාස්ම විච්ඡේදනය", "සාන්ද්‍රණ අනුක්‍රමණයට එරෙහිව ගමන් කිරීමට ATP අවශ්‍ය වේ."),
    q("සජීවී ශාක සෛලයක් අධි-තානික (සාන්ද්‍ර සීනි) ද්‍රාවණයක තැබූ විට සිදුවන්නේ කුමක්ද?", "ප්ලාස්ම විච්ඡේදනය", "සෛලය පිපිරී යාම", "ශූනතාව වැඩිවීම", "සෛල විභාජනය වීම", "සෛලයෙන් ජලය පිටතට යාමෙන් ප්ලාස්ම පටලය සෛල බිත්තියෙන් වෙන්වේ."),
    q("කුමන සත්ව කාණ්ඩයේ පූර්ණ සෛල බිත්තියක් නොමැති නිසා අධෝ-තානික ද්‍රාවණයකදී පුපුරා යා හැකිද?", "සත්ව සෛල", "ශාක සෛල", "දිලීර සෛල", "බැක්ටීරියා සෛල", "සත්ව සෛලවල සෛල බිත්ති නොමැති බැවින් අධික ජල අවශෝෂණයේදී පුපුරා යයි.")
  )
}
